.amp-title-toggle{display:none}
@media(max-width:991px){#abe-preview{width:100%;max-width:100%;margin:0 auto;overflow-wrap:break-word}.nav-bar{width:100%;margin-left:0;margin-right:0;box-sizing:border-box}.nav-bar>.row{width:100%;margin:0}.amp-site-header .head-contact{display:flex;justify-content:center;flex-wrap:wrap;gap:6px 12px}.amp-site-header .head-contact li{display:inline-flex;align-items:center;font-size:12px;line-height:1.7}.amp-site-header .head-contact a{font-size:12px}.search-form{display:flex;align-items:stretch;gap:6px;width:100%;max-width:600px;margin:0 auto}.search-form input[type=search]{width:auto;min-width:0;flex:1;font-size:16px;height:46px;padding:10px 12px}.search-form button{display:flex;align-items:center;justify-content:center;flex:0 0 46px;min-height:46px;padding:10px;background:#142d82;color:#fff}.search-form button svg{width:22px;height:22px;display:block}.menu-btn{min-height:44px;font-size:15px}.report-list .rport-title a{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden;font-size:18px;line-height:1.55}.report-list .rport-detail p{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden;font-size:14px;line-height:1.8}.rd-details-container{padding:23px 15px}.rd-img{display:none;float:none}.rd-details{padding-left:0}.rd-title{font-size:21px;line-height:1.5;text-align:left;display:-webkit-box;-webkit-line-clamp:5;-webkit-box-orient:vertical;overflow:hidden}.rd-title.is-expanded{display:block;-webkit-line-clamp:unset;overflow:visible}.amp-title-toggle{display:inline-flex;align-items:center;min-height:44px;padding:6px 0;font-size:13px;color:#173c8b;background:none;border-bottom:1px solid #b9cae6}.detail-list{display:flex;flex-direction:column;gap:7px}.detail-list li{font-size:13px;line-height:1.8;text-align:left}.btn-wrapper{display:flex;flex-direction:column;gap:9px}.btn-sample{min-height:44px;padding:10px 14px;line-height:1.5;margin:0;text-align:center}.tabContent{max-width:100%;min-width:0;padding:18px 12px;overflow-wrap:anywhere}.tabContent table{display:block;width:100%;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch}.tabContent table td{min-width:110px;font-size:13px;padding:10px}.amp-site-footer .footer-contact-background>.col-6{width:100%;float:none;border:0}.amp-site-footer .footer-contact-no{font-size:13px;overflow-wrap:anywhere}select,input,textarea{font-size:16px;max-width:100%}.purchase button,.purchase .btn-buy{min-height:44px}}
@media(max-width:991px){#sidebar{max-width:calc(100vw - 32px);box-sizing:border-box}.close-btn a{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-width:80px;min-height:44px}.close-btn svg{width:18px;height:18px}.sidebar-item,.sidebar-menu ul li a{display:flex;align-items:center;min-height:44px;box-sizing:border-box}.sidebar-menu h4{min-height:44px;box-sizing:border-box}}
